from __future__ import annotations

import json
import re
import sqlite3
from collections import deque
from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from packaging.version import InvalidVersion, Version


SCHEMA = """
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS components (
    id INTEGER PRIMARY KEY,
    service TEXT NOT NULL,
    ecosystem TEXT NOT NULL,
    name TEXT NOT NULL,
    version TEXT NOT NULL,
    manual INTEGER NOT NULL DEFAULT 0,
    UNIQUE(service, ecosystem, name, version)
);
CREATE TABLE IF NOT EXISTS vulnerabilities (
    id TEXT NOT NULL,
    component_name TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    PRIMARY KEY(id, component_name)
);
CREATE TABLE IF NOT EXISTS dependencies (
    id INTEGER PRIMARY KEY,
    dependent_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
    dependency_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
    manual INTEGER NOT NULL DEFAULT 0,
    UNIQUE(dependent_id, dependency_id)
);
CREATE TABLE IF NOT EXISTS sources (
    id INTEGER PRIMARY KEY,
    service TEXT NOT NULL,
    name TEXT NOT NULL,
    UNIQUE(service, name)
);
CREATE TABLE IF NOT EXISTS component_sources (
    component_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
    source_id INTEGER NOT NULL REFERENCES sources(id) ON DELETE CASCADE,
    PRIMARY KEY(component_id, source_id)
);
CREATE TABLE IF NOT EXISTS dependency_sources (
    dependency_id INTEGER NOT NULL REFERENCES dependencies(id) ON DELETE CASCADE,
    source_id INTEGER NOT NULL REFERENCES sources(id) ON DELETE CASCADE,
    PRIMARY KEY(dependency_id, source_id)
);
CREATE TABLE IF NOT EXISTS osv_vulnerabilities (
    source TEXT NOT NULL,
    id TEXT NOT NULL,
    package_name TEXT NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    severity_default INTEGER NOT NULL DEFAULT 0,
    withdrawn TEXT,
    conditions TEXT NOT NULL,
    PRIMARY KEY(source, id, package_name)
);
CREATE TABLE IF NOT EXISTS exemption_requests (
    id TEXT PRIMARY KEY,
    service TEXT NOT NULL,
    ecosystem TEXT NOT NULL,
    name TEXT NOT NULL,
    version TEXT NOT NULL,
    vulnerability TEXT NOT NULL,
    matched_name TEXT NOT NULL,
    source TEXT,
    created_at TEXT NOT NULL,
    applicant TEXT NOT NULL,
    reason TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'revoked')),
    decided_at TEXT,
    approver TEXT,
    decision_note TEXT,
    approved_severity TEXT,
    revoked_at TEXT,
    revoker TEXT,
    revoke_note TEXT
);
CREATE TABLE IF NOT EXISTS exemption_events (
    id INTEGER PRIMARY KEY,
    request_id TEXT NOT NULL,
    seq INTEGER NOT NULL,
    occurred_at TEXT NOT NULL,
    actor TEXT NOT NULL,
    action TEXT NOT NULL CHECK (action IN ('request', 'approve', 'reject', 'revoke')),
    reason TEXT NOT NULL,
    from_status TEXT,
    to_status TEXT NOT NULL,
    UNIQUE(request_id, seq)
);
"""

SEVERITY_RANK = {"low": 1, "medium": 2, "high": 3, "critical": 4}

SUPPORTED_ECOSYSTEMS = ("pypi", "npm")

EXEMPTION_PENDING = "pending"
EXEMPTION_APPROVED = "approved"
EXEMPTION_REJECTED = "rejected"
EXEMPTION_REVOKED = "revoked"
# Terminal states a request never leaves; every other state is a live request.
EXEMPTION_TERMINAL = frozenset({EXEMPTION_REJECTED, EXEMPTION_REVOKED})
# Statuses that block a fresh request for the same scope while in force.
EXEMPTION_OPEN = frozenset({EXEMPTION_PENDING, EXEMPTION_APPROVED})


def utc_now() -> datetime:
    """Current time as a timezone-aware UTC datetime."""
    return datetime.now(timezone.utc)


def parse_timestamp(value: object, context: str) -> datetime:
    """Parse an ISO 8601 timestamp that must carry explicit timezone info.

    The returned datetime is timezone-aware so it can be compared with UTC
    instants. Naive timestamps are rejected because their meaning is
    ambiguous.
    """
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{context}必须为非空时间字符串")
    text = value.strip()
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as error:
        raise ValueError(f"{context}时间无效: {text!r}") from error
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError(f"{context}必须带有时区信息: {text!r}")
    return parsed.astimezone(timezone.utc)


def format_timestamp(moment: datetime) -> str:
    """Render a datetime as a canonical fixed-length UTC string.

    All instants are stored in this one form (``...Z``, six-digit
    microseconds), so lexicographic string comparison in SQL and Python is
    strictly chronological.
    """
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    return moment.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def normalize_pypi_name(name: str) -> str:
    """Normalize a PyPI package name per PEP 503.

    Case is folded and runs of hyphens, underscores and dots are treated as
    equivalent. Component identities are kept verbatim; this normalization
    is only used to match OSV records against components.
    """
    return re.sub(r"[-_.]+", "-", name).lower()


def _parse_pep440_version(value: object, context: str) -> Version:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{context} 必须为非空字符串")
    try:
        return Version(value.strip())
    except InvalidVersion as error:
        raise ValueError(f"无法解析的版本 {value!r}（{context}）") from error


def _parse_withdrawn(value: object) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError("withdrawn 必须为非空时间戳字符串")
    timestamp = value.strip()
    try:
        datetime.fromisoformat(timestamp)
    except ValueError as error:
        raise ValueError(f"withdrawn 时间戳无效: {timestamp!r}") from error
    return timestamp


def _osv_entry_package(entry: object, index: int) -> tuple[str, str]:
    """Validate one affected entry's package target.

    Returns the declared (stripped) package name and its normalized PyPI
    form. Only PyPI entries are accepted; anything else rejects the import.
    """
    if not isinstance(entry, dict):
        raise ValueError(f"affected[{index}] 必须为对象")
    package = entry.get("package")
    if not isinstance(package, dict):
        raise ValueError(f"affected[{index}].package 必须为对象")
    ecosystem = package.get("ecosystem")
    if not isinstance(ecosystem, str) or not ecosystem.strip():
        raise ValueError(f"affected[{index}].package.ecosystem 必须为非空字符串")
    if ecosystem.strip().lower() != "pypi":
        raise ValueError(
            f"affected[{index}] 的生态系统 {ecosystem!r} 不受支持，仅支持 PyPI"
        )
    name = package.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError(f"affected[{index}].package.name 必须为非空字符串")
    raw_name = name.strip()
    return raw_name, normalize_pypi_name(raw_name)


def _osv_explicit_conditions(entry: dict, index: int) -> list[dict]:
    """The explicit-version conditions declared by one affected entry."""
    conditions: list[dict] = []
    versions = entry.get("versions", [])
    if not isinstance(versions, list):
        raise ValueError(f"affected[{index}].versions 必须为数组")
    for version in versions:
        parsed = _parse_pep440_version(version, f"affected[{index}].versions")
        conditions.append({"type": "explicit", "version": str(parsed)})
    return conditions


def _osv_intervals_from_events(events: object, range_context: str) -> list[dict]:
    """Interpret one range's event list as version intervals.

    An ``introduced`` event opens a new interval; a ``fixed`` or
    ``last_affected`` event closes the currently open one. Any other order
    (a second ``introduced`` while one is open, or a closing event with no
    open interval) is rejected, as are unknown event types and events that
    are not exactly one field. ``range_context`` locates the range in error
    messages (``affected[i].ranges[j]``).
    """
    if not isinstance(events, list) or not events:
        raise ValueError(f"{range_context}.events 必须为非空数组")
    intervals: list[dict] = []
    opened = False
    for event_index, event in enumerate(events):
        event_context = f"{range_context}.events[{event_index}]"
        if not isinstance(event, dict):
            raise ValueError(f"{event_context} 必须为对象")
        keys = set(event.keys())
        if len(keys) != 1:
            raise ValueError(f"{event_context} 必须恰好包含一个事件字段")
        key = next(iter(keys))
        if key not in ("introduced", "fixed", "last_affected"):
            raise ValueError(f"{event_context} 的事件类型 {key!r} 不受支持")
        value = event[key]
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{event_context}.{key} 必须为非空字符串")
        value = value.strip()
        if key == "introduced":
            if opened:
                raise ValueError(
                    f"{event_context} "
                    "事件次序非法：introduced 之后不能再次 introduced"
                )
            intervals.append(
                {"type": "interval", "introduced": value,
                 "fixed": None, "last_affected": None}
            )
            opened = True
        else:
            if not opened:
                raise ValueError(
                    f"{event_context} 事件次序非法：{key} 之前缺少 introduced"
                )
            intervals[-1][key] = value
            opened = False
    return intervals


def _validate_osv_interval(interval: dict, range_context: str) -> None:
    """Check one interval's versions parse and its bounds are not inverted.

    ``introduced`` of ``"0"`` means no lower bound and is exempt from both
    parsing and the inversion comparisons.
    """
    introduced = interval["introduced"]
    if introduced != "0":
        _parse_pep440_version(introduced, f"{range_context}.introduced")
    if interval["fixed"] is not None:
        fixed = interval["fixed"]
        _parse_pep440_version(fixed, f"{range_context}.fixed")
        if introduced != "0" and not (Version(introduced) < Version(fixed)):
            raise ValueError(
                f"{range_context} 区间倒置："
                f"introduced {introduced} 必须小于 fixed {fixed}"
            )
    if interval["last_affected"] is not None:
        last_affected = interval["last_affected"]
        _parse_pep440_version(last_affected, f"{range_context}.last_affected")
        if introduced != "0" and not (
            Version(introduced) <= Version(last_affected)
        ):
            raise ValueError(
                f"{range_context} 区间倒置："
                f"introduced {introduced} 不能大于 last_affected {last_affected}"
            )


def _osv_range_conditions(entry: dict, index: int) -> list[dict]:
    """The interval conditions declared by one affected entry's ranges."""
    conditions: list[dict] = []
    ranges = entry.get("ranges", [])
    if not isinstance(ranges, list):
        raise ValueError(f"affected[{index}].ranges 必须为数组")
    for range_index, range_entry in enumerate(ranges):
        range_context = f"affected[{index}].ranges[{range_index}]"
        if not isinstance(range_entry, dict):
            raise ValueError(f"{range_context} 必须为对象")
        range_type = range_entry.get("type")
        if not isinstance(range_type, str) or not range_type.strip():
            raise ValueError(f"{range_context}.type 必须为非空字符串")
        if range_type.strip().upper() != "ECOSYSTEM":
            raise ValueError(
                f"{range_context} 的范围类型 {range_type!r} 不受支持，仅支持 ECOSYSTEM"
            )
        intervals = _osv_intervals_from_events(
            range_entry.get("events"), range_context
        )
        for interval in intervals:
            _validate_osv_interval(interval, range_context)
        conditions.extend(intervals)
    return conditions


def _parse_osv_entry(entry: object, index: int) -> tuple[str, list[dict]]:
    """Validate one affected entry and return its package and conditions.

    Every entry must independently declare at least one version condition —
    a non-empty explicit versions list or at least one valid ECOSYSTEM
    range. Conditions are never shared between entries, so an entry without
    its own conditions rejects the import no matter what any identically or
    equivalently named sibling entry declares.
    """
    raw_name, package_name = _osv_entry_package(entry, index)
    conditions = _osv_explicit_conditions(entry, index)
    conditions.extend(_osv_range_conditions(entry, index))
    if not conditions:
        raise ValueError(
            f"affected[{index}]（包 {raw_name}）缺少版本条件："
            "必须提供非空 versions 或至少一个合法 ECOSYSTEM ranges"
        )
    return package_name, conditions


def _parse_osv_affected(affected: object) -> dict[str, list[dict]]:
    """Validate the affected entries of one OSV record.

    Returns a mapping of normalized package name to the version conditions
    declared for that package, merged across every entry targeting the same
    normalized name. Merging only ever combines conditions of entries that
    each validated on their own; identical or normalization-equivalent
    package names never let one entry borrow another entry's conditions.
    Other ecosystems, unknown range types/events, malformed event orders,
    inverted intervals and unparseable versions reject the whole import.
    """
    if not isinstance(affected, list) or not affected:
        raise ValueError("affected 必须为非空数组")
    packages: dict[str, list[dict]] = {}
    for index, entry in enumerate(affected):
        package_name, conditions = _parse_osv_entry(entry, index)
        packages.setdefault(package_name, []).extend(conditions)
    return packages


def parse_osv_record(record: object) -> list[dict]:
    """Validate one OSV record and return its normalized rows.

    Each returned row describes one (package, version conditions) pair. The
    whole record is validated before anything is returned, so callers can
    reject the entire import on the first invalid record.
    """
    if not isinstance(record, dict):
        raise ValueError("记录必须为 JSON 对象")
    identifier = record.get("id")
    if not isinstance(identifier, str) or not identifier.strip():
        raise ValueError("id 必须为非空字符串")
    identifier = identifier.strip()

    packages = _parse_osv_affected(record.get("affected"))

    severity = "medium"
    severity_default = True
    database_specific = record.get("database_specific")
    if database_specific is not None:
        if not isinstance(database_specific, dict):
            raise ValueError("database_specific 必须为对象")
        declared = database_specific.get("severity")
        if declared is not None:
            if not isinstance(declared, str) or declared.strip().lower() not in SEVERITY_RANK:
                raise ValueError(
                    f"database_specific.severity {declared!r} 不受支持，"
                    "仅接受 low、medium、high、critical"
                )
            severity = declared.strip().lower()
            severity_default = False

    withdrawn = None
    if "withdrawn" in record:
        withdrawn = _parse_withdrawn(record["withdrawn"])

    return [
        {
            "id": identifier,
            "package_name": package_name,
            "severity": severity,
            "severity_default": severity_default,
            "withdrawn": withdrawn,
            "conditions": conditions,
        }
        for package_name, conditions in packages.items()
    ]


def _condition_matches(condition: dict, version: Version) -> bool:
    if condition["type"] == "explicit":
        return version == Version(condition["version"])
    if condition["type"] != "interval":
        return False
    introduced = condition["introduced"]
    if introduced != "0" and version < Version(introduced):
        return False
    if condition["fixed"] is not None and version >= Version(condition["fixed"]):
        return False
    if condition["last_affected"] is not None and version > Version(
        condition["last_affected"]
    ):
        return False
    return True


def _format_condition(condition: dict) -> str:
    if condition["type"] == "explicit":
        return f"=={condition['version']}"
    parts: list[str] = []
    introduced = condition["introduced"]
    if introduced != "0":
        parts.append(f">={introduced}")
    if condition["fixed"] is not None:
        parts.append(f"<{condition['fixed']}")
    if condition["last_affected"] is not None:
        parts.append(f"<={condition['last_affected']}")
    return ",".join(parts) if parts else "*"


@dataclass(frozen=True)
class Summary:
    components: int
    affected_components: int

"""Business regression tests for OSV matching of PyPI development releases.

Users register several development builds of one package (``1.0.dev9``,
``1.0.dev10`` and so on); a local OSV source then decides which builds and
their dependents are affected. These tests lock how those dev builds take
part in version comparison and impact reporting through the public catalog
behavior — components are registered, a local OSV source is imported, and the
impacts a user would query are inspected — rather than only checking that
version strings parse.

They pin the following rules:

* dev releases sort by PEP 440 before both the prereleases (``1.0a1``) and
  the final release (``1.0``) of the same release, and the ``devN`` suffix
  compares numerically (``dev9 < dev10``), never lexically;
* a ``fixed`` interval partitions on the dev number: introduced
  ``1.0.dev2`` / fixed ``1.0.dev10`` reaches ``dev2`` and ``dev9`` but not
  ``dev1``, ``dev10`` or final ``1.0``; a ``last_affected`` upper bound
  includes its dev endpoint while final releases stay outside;
* a fix at the first prerelease must not lump same-release dev builds
  together with it: introduced ``1.0.dev2`` / fixed ``1.0a1`` still reaches
  the dev builds from ``dev2`` up while ``1.0a1`` and ``1.0`` stay out;
* explicit ``versions`` match by PEP 440 equality: a source listing
  ``1.0.dev2`` also reaches a component registered as ``1.0.0.dev2``, but
  not ``dev3`` or the final release — and equivalence never merges the two
  spellings in the directory: impact records, the component count and the
  versions embedded in dependency paths each keep their registered text;
* dependency propagation, summary counts and the risk report follow the
  actually hit dev build — an upper component depending on a hit dev build
  is indirectly affected on a path ending at that build with that endpoint's
  conditions, while depending only on an unhit dev build gives no impact;
* a dev interval that is inverted under PEP 440 (e.g. introduced
  ``1.0.dev10`` fixed ``1.0.dev2``) rejects the import and leaves the
  previous source content in place.
"""

import unittest

from supply_guard.catalog import Catalog


def osv_record(identifier, package="lib", **affected):
    entry = {"package": {"ecosystem": "PyPI", "name": package}}
    entry.update(affected)
    return {"id": identifier, "affected": [entry]}


def dev_range(*events):
    return [{"type": "ECOSYSTEM", "events": [dict([event]) for event in events]}]


DEV_BUILDS = ("1.0.dev1", "1.0.dev2", "1.0.dev9", "1.0.dev10")


class DevIntervalEndpointTests(unittest.TestCase):
    """Dev builds as introduced / fixed / last_affected interval endpoints."""

    def setUp(self) -> None:
        self.catalog = Catalog()
        for version in (*DEV_BUILDS, "1.0a1", "1.0"):
            self.catalog.add_component("api", "pypi", "lib", version)

    def tearDown(self) -> None:
        self.catalog.close()

    def records_by_version(self):
        return {r["component"]["version"]: r for r in self.catalog.impact()}

    def test_fixed_interval_partitions_on_dev_number(self) -> None:
        # introduced 1.0.dev2, fixed 1.0.dev10: dev2 and dev9 are in (9 is
        # compared as a number — a lexical sort would place it past 10);
        # dev1 lies below the lower bound, dev10 is the excluded fix and
        # final 1.0 sorts above every dev build and stays out.
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=dev_range(
                        ("introduced", "1.0.dev2"), ("fixed", "1.0.dev10")
                    ),
                )
            ],
        )
        by_version = self.records_by_version()
        self.assertEqual(set(by_version), {"1.0.dev2", "1.0.dev9"})
        condition = ">=1.0.dev2,<1.0.dev10"
        for version in ("1.0.dev2", "1.0.dev9"):
            record = by_version[version]
            self.assertTrue(record["direct"])
            self.assertEqual(record["matched_conditions"], [condition])
            self.assertEqual(record["path"], [record["component"]])
        for version in ("1.0.dev1", "1.0.dev10", "1.0"):
            self.assertNotIn(version, by_version)

    def test_last_affected_includes_dev_endpoint_but_not_release(self) -> None:
        # Same endpoints with last_affected: the dev10 build itself is still
        # affected; final 1.0 remains above the bound and out of the report.
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=dev_range(
                        ("introduced", "1.0.dev2"),
                        ("last_affected", "1.0.dev10"),
                    ),
                )
            ],
        )
        by_version = self.records_by_version()
        self.assertEqual(
            set(by_version), {"1.0.dev2", "1.0.dev9", "1.0.dev10"}
        )
        condition = ">=1.0.dev2,<=1.0.dev10"
        for record in by_version.values():
            self.assertEqual(record["matched_conditions"], [condition])
        self.assertNotIn("1.0", by_version)

    def test_dev_builds_below_prerelease_fix_remain_affected(self) -> None:
        # Dev builds sort before every prerelease of the same release: with
        # the fix released as 1.0a1, dev2..dev10 are still affected while
        # 1.0a1 itself and final 1.0 are not. Same-release membership must
        # never pull the prerelease/release into the dev interval.
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=dev_range(
                        ("introduced", "1.0.dev2"), ("fixed", "1.0a1")
                    ),
                )
            ],
        )
        by_version = self.records_by_version()
        self.assertEqual(
            set(by_version), {"1.0.dev2", "1.0.dev9", "1.0.dev10"}
        )
        for record in by_version.values():
            self.assertEqual(
                record["matched_conditions"], [">=1.0.dev2,<1.0a1"]
            )
        self.assertNotIn("1.0a1", by_version)
        self.assertNotIn("1.0", by_version)

    def test_open_ended_dev_introduced_includes_dev1_as_below_bound(self) -> None:
        # An open range starting at dev9 has no upper bound: later dev
        # builds, the prerelease and the final release are all reached;
        # only builds strictly below dev9 (dev1, dev2) stay out.
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=dev_range(("introduced", "1.0.dev9")),
                )
            ],
        )
        by_version = self.records_by_version()
        self.assertEqual(
            set(by_version), {"1.0.dev9", "1.0.dev10", "1.0a1", "1.0"}
        )
        self.assertNotIn("1.0.dev1", by_version)
        self.assertNotIn("1.0.dev2", by_version)


class DevExplicitEquivalenceTests(unittest.TestCase):
    """Explicit conditions use PEP 440 equality and keep identity verbatim."""

    def setUp(self) -> None:
        self.catalog = Catalog()

    def tearDown(self) -> None:
        self.catalog.close()

    def records_by_version(self):
        return {r["component"]["version"]: r for r in self.catalog.impact()}

    def test_zero_padded_release_segment_hits_equivalent_spelling(self) -> None:
        # A zero release segment is implicit: 1.0.dev2 == 1.0.0.dev2 under
        # PEP 440, so one explicit condition reaches the 1.0.0.dev2
        # registration as well; dev3 and final 1.0 stay out.
        for version in ("1.0.dev2", "1.0.0.dev2", "1.0.dev3", "1.0"):
            self.catalog.add_component("api", "pypi", "lib", version)
        self.catalog.import_osv(
            "src", [osv_record("CVE-1", versions=["1.0.dev2"])]
        )
        by_version = self.records_by_version()
        self.assertEqual(set(by_version), {"1.0.dev2", "1.0.0.dev2"})
        for version, record in by_version.items():
            self.assertTrue(record["direct"])
            self.assertEqual(record["component"]["version"], version)
            self.assertEqual(record["path"], [record["component"]])
            # The condition is rendered in the source-side normalized form;
            # the component identity still carries the registered spelling.
            self.assertEqual(record["matched_conditions"], ["==1.0.dev2"])

    def test_equivalent_spellings_remain_two_components(self) -> None:
        # Equality of the matching condition never merges directory rows:
        # two registrations stay two components with two impact records, and
        # every path keeps the version text each component was registered
        # with.
        self.catalog.add_component("api", "pypi", "lib", "1.0.dev2")
        self.catalog.add_component("api", "pypi", "lib", "1.0.0.dev2")
        self.catalog.import_osv(
            "src", [osv_record("CVE-1", versions=["1.0.dev2"])]
        )
        self.assertEqual(self.catalog.summary().components, 2)
        records = self.records_by_version()
